def count_negative_columns(matrix):
    if not matrix or not matrix[0]:
        return []
    num_columns = len(matrix[0])
    result = [0] * num_columns
    for col in range(num_columns):
        for row in matrix:
            if row[col] < 0:
                result[col] += 1
    return result
```

